package dev.ashtonite365.apex.features.inventory.buttons

import net.minecraft.network.chat.Component
import dev.ashtonite365.apex.Apex
import dev.ashtonite365.apex.util.Faults
import dev.ashtonite365.apex.util.Client
import dev.ashtonite365.apex.util.ShareCodes

object ButtonPresets {
	private const val FORMAT_PREFIX = "NEUBUTTONS/"

	const val EMPTY = "TkVVQlVUVE9OUy9bXQ=="

	const val SIMPLE = ""

	const val ALL_WARPS = ""

	fun decode(text: String): List<InventoryButton>? =
		ShareCodes.fromShareCode<List<String>>(FORMAT_PREFIX, text)?.mapNotNull(::decodeButton)

	private fun decodeButton(json: String): InventoryButton? {
		val button = Faults.attempt<InventoryButton?>("Could not import button") { Apex.json.decodeFromString<InventoryButton>(json) }.orElse { null }

		if (button?.icon?.startsWith("extra:") == true) Client.showChat(Component.translatable("apex.inventory-buttons.import-failed"))
		return button
	}

	fun encode(buttons: List<InventoryButton>): String =
		ShareCodes.toShareCode(FORMAT_PREFIX, buttons.map { Apex.json.encodeToString(InventoryButton.serializer(), it) })
}
